99	export class SpendCapError extends Error {
100	  constructor(public readonly capUsd: number, public readonly attemptedUsd: number) {
101	    super(`spend cap $${capUsd} would be exceeded (attempted total $${attemptedUsd.toFixed(4)}) — battery aborted`);
102	    this.name = 'SpendCapError';
103	  }
104	}
105	
106	export interface Spend {
107	  readonly usd: number;
108	  /** Add `amount` (negatives ignored); throw SpendCapError BEFORE recording if it would exceed the cap. */
109	  charge(amount: number, label: string): void;
110	}
111	
112	/** A hard total-spend ceiling. `charge` throws the instant a charge would cross `capUsd`. */
113	export function makeSpend(capUsd: number): Spend {
114	  let usd = 0;
115	  return {
116	    get usd() {
117	      return usd;
118	    },
119	    charge(amount: number) {
120	      const next = usd + Math.max(0, amount);
121	      if (next > capUsd) throw new SpendCapError(capUsd, next);
122	      usd = next;
123	    },
124	  };
125	}
