173	/** Pre-flight: fail loud with a clear message if the beekeeper schema isn't applied on the live PG. */
174	async function assertSchema(sql: postgres.Sql): Promise<void> {
175	  const rows = await sql<{ ok: boolean }[]>`
176	    SELECT to_regclass('harness_shared.beekeeper_runs') IS NOT NULL
177	       AND to_regclass('iq_battery_cases') IS NOT NULL AS ok`;
178	  if (!rows[0]?.ok) {
179	    throw new Error(
180	      'beekeeper/iq-battery schema missing on the live org PG — apply migrations 179 + 180 (db:migrate) before running the baseline.',
181	    );
182	  }
183	}
