185	/**
186	 * Load the seeded corpus back from iq_battery_cases — the in-memory corpus data carries NO `id`
187	 * (it's assigned at seed time via generateStableCaseId), and the battery keys runs by case id. One
188	 * single-value-bound query per variant (bulletproof binds), capped at `casesPerVariant`.
189	 */
190	async function loadSeededCorpus(
191	  sql: postgres.Sql,
192	  variants: TaskVariant[],
193	  casesPerVariant: number,
194	): Promise<CorpusCase[]> {
195	  const corpus: CorpusCase[] = [];
196	  for (const variant of variants) {
197	    const rows = await sql<
198	      {
199	        id: string;
200	        variant: string;
201	        title: string;
202	        prompt: string;
203	        ground_truth: Record<string, unknown>;
204	        rubric: unknown;
205	        rotation_index: number;
206	      }[]
207	    >`
208	      SELECT id, variant, title, prompt, ground_truth, rubric, rotation_index
209	        FROM iq_battery_cases
210	       WHERE variant = ${variant}
211	       ORDER BY rotation_index
212	       LIMIT ${casesPerVariant}`;
213	    for (const r of rows) {
214	      // jsonb may arrive parsed (object) or raw (string) depending on the pool's parse config —
215	      // normalize so groundTruth/rubric are always objects.
216	      const asObj = (v: unknown, dflt: unknown): unknown => {
217	        if (v == null) return dflt;
218	        if (typeof v === 'string') {
219	          try {
220	            return JSON.parse(v);
221	          } catch {
222	            return dflt;
223	          }
224	        }
225	        return v;
226	      };
227	      corpus.push({
228	        id: r.id,
229	        variant: r.variant as TaskVariant,
230	        title: r.title,
231	        prompt: r.prompt,
232	        groundTruth: asObj(r.ground_truth, {}) as Record<string, unknown>,
233	        rubric: asObj(r.rubric, { dimensions: [] }) as Rubric,
234	        rotationIndex: r.rotation_index,
235	        createdAt: new Date(),
236	      });
237	    }
238	  }
239	  return corpus;
240	}
