242	/** Transfer the freshly-recorded beekeeper_scores → iq_battery_metrics (the recurrence + Tests-tab source). */
243	async function transferMetrics(sql: postgres.Sql, instanceId: string): Promise<number> {
244	  const runs = await sql<{ run_id: string; case_id: string; case_variant: string }[]>`
245	    SELECT run_id, case_id, case_variant FROM harness_shared.beekeeper_runs WHERE instance_id = ${instanceId}`;
246	  let transferred = 0;
247	  for (const run of runs) {
248	    const scores = await sql<
249	      {
250	        success: boolean;
251	        tokens_per_task: number | null;
252	        time_to_green_secs: number | null;
253	        first_attempt_pass: boolean;
254	        recurrence: number;
255	        escalation: boolean;
256	        recall_hit: number;
257	      }[]
258	    >`
259	      SELECT success, tokens_per_task, time_to_green_secs, first_attempt_pass, recurrence, escalation, recall_hit
260	        FROM harness_shared.beekeeper_scores WHERE run_id = ${run.run_id} LIMIT 1`;
261	    const s = scores[0];
262	    if (!s) continue;
263	    // Idempotent transfer (D-005): iq_battery_metrics.run_id is a UUID column but the beekeeper
264	    // run_id is TEXT, so we can't store the run_id directly. Derive a DETERMINISTIC uuid from it
265	    // (md5(text)::uuid) so a re-run of the same beekeeper run maps to the SAME metric row and
266	    // ON CONFLICT (run_id, case_id) overwrites it — instead of gen_random_uuid() appending a fresh
267	    // duplicate every transfer (the bug that accreted 19 dup rows over the dev runs).
268	    await sql`
269	      INSERT INTO iq_battery_metrics (
270	        run_id, case_id, variant, success, tokens_per_solved_task, time_to_green_secs,
271	        first_attempt_pass, recurrence, escalation, recall_hit
272	      ) VALUES (
273	        md5(${run.run_id})::uuid, ${run.case_id}, ${run.case_variant}, ${s.success}, ${s.tokens_per_task},
274	        ${s.time_to_green_secs}, ${s.first_attempt_pass}, ${s.recurrence}, ${s.escalation}, ${s.recall_hit}
275	      )
276	      ON CONFLICT (run_id, case_id) DO UPDATE SET
277	        variant = EXCLUDED.variant,
278	        success = EXCLUDED.success,
279	        tokens_per_solved_task = EXCLUDED.tokens_per_solved_task,
280	        time_to_green_secs = EXCLUDED.time_to_green_secs,
281	        first_attempt_pass = EXCLUDED.first_attempt_pass,
282	        recurrence = EXCLUDED.recurrence,
283	        escalation = EXCLUDED.escalation,
284	        recall_hit = EXCLUDED.recall_hit,
285	        collected_at = now()`;
286	    transferred += 1;
287	  }
288	  return transferred;
289	}
