291	/** Build the live deps (cap-wrapped solver + judge) + config, run the battery, transfer + report. */
292	export async function runGen0Battery(args: Gen0Args): Promise<void> {
293	  const workspaceId = args.workspaceId ?? activeWorkspaceId();
294	  if (!args.harness) throw new Error('--harness=<slug> is required (the harness the solver bees spawn into)');
295	
296	  // Pin solver bees to opus-4-8 @ xhigh deterministically (bees have no committed ROLE_MODEL_DEFAULTS
297	  // floor), and ENABLE the shared AIMD governor so a bee 429 halves the effective concurrency cap
298	  // (the "lower cap" half of the hit-limit → lower-cap → relaunch loop).
299	  const priorEnv = {
300	    AGENT_MODELS: process.env.AGENT_MODELS,
301	    PAPERCUSP_AGENT_GOVERNOR: process.env.PAPERCUSP_AGENT_GOVERNOR,
302	    PAPERCUSP_AGENT_GOVERNOR_PG: process.env.PAPERCUSP_AGENT_GOVERNOR_PG,
303	    LLM_TEST_BACKEND: process.env.LLM_TEST_BACKEND,
304	  };
305	  try {
306	    const merged = { ...(priorEnv.AGENT_MODELS ? safeJson(priorEnv.AGENT_MODELS) : {}), bee: 'opus:xhigh' };
307	    process.env.AGENT_MODELS = JSON.stringify(merged);
308	    process.env.PAPERCUSP_AGENT_GOVERNOR = '1';
309	    process.env.PAPERCUSP_AGENT_GOVERNOR_PG = '1';
310	    // The judge is an IN-PROCESS llmCall on THIS box; llm-client's default anthropic-direct
311	    // backend rides the owner's volatile ~/.claude session and shares its rate bucket. Route the
312	    // judge through the claude CLI on the same clean OAuth token the bees already use
313	    // (CLAUDE_CODE_OAUTH_TOKEN), unless the caller explicitly set a backend. (Originally also
314	    // dodged the pre-EI-399 default that pointed at the dead :3456 router and wedged the
315	    // sequential battery in an endless retry loop.)
