63	export interface BeeRunConfig {
64	  /** Bounded wall-clock per case — on overrun the run is `errored`, never hangs the battery. */
65	  timeoutMs: number;
66	  /** Poll cadence while awaiting a terminal state. */
67	  pollMs: number;
68	  /** Max RELAUNCHES when a bee fails on a transient rate-limit/overload (the owner's hit-limit →
69	   *  relaunch loop; the fleet AIMD governor lowers concurrency in parallel). 0 = no retry. */
70	  maxRateRetries: number;
71	  /** Floor backoff before a rate-limit relaunch; the server's retry-after wins when larger. */
