75	/**
76	 * Build the real `runInstance`: spawn one bee for the case, await a terminal state, map it, and
77	 * return an `InstanceRunHandle` keyed to the bee's spawn id (which IS the instanceId collectAndDistill
78	 * reads). Throws on spawn rejection, timeout, or an invalid (cancelled/reaped) terminal.
79	 */
80	export function makeBeeRunInstance(cfg: BeeRunConfig, deps: BeeRunDeps) {
81	  const handleFor = async (spawnId: string, variant: string): Promise<InstanceRunHandle> => ({
82	    instanceId: spawnId,
83	    instanceUrl: `bee://${spawnId}`,
84	    targetSlug: variant,
85	    costUsd: await deps.loadCost(spawnId).catch(() => 0),
86	  });
87	
88	  return async (input: BeekeeperRunInput): Promise<InstanceRunHandle> => {
89	    // Relaunch loop: a bee that FAILS on a transient rate-limit / overload is re-spawned (a FRESH
90	    // bee) up to maxRateRetries, after a backoff (the server's retry-after, floored). The fleet
91	    // AIMD governor halves the effective concurrency in parallel, so each relaunch lands at a
92	    // lower cap — the owner's hit-limit → lower-cap → relaunch → converge loop.
93	    for (let attempt = 0; ; attempt++) {
94	      const res = await deps.spawn({ brief: input.case.prompt, runInput: input });
95	      if (!res.ok || !res.spawnId) {
96	        throw new Error(`runInstance: spawn rejected for case ${input.case.id}: ${res.error ?? 'unknown'}`);
97	      }
98	      const spawnId = res.spawnId;
99	
100	      const deadline = deps.now() + cfg.timeoutMs;
101	      let status: string | null = null;
102	      while (deps.now() < deadline) {
103	        await deps.sleep(cfg.pollMs);
104	        status = await deps.pollStatus(spawnId);
105	        if (status && TERMINAL.has(status)) break;
106	      }
107	
108	      if (!status || !TERMINAL.has(status)) {
109	        throw new Error(
110	          `runInstance: bee ${spawnId} did not reach a terminal state within ${cfg.timeoutMs}ms (last=${status ?? 'unseen'})`,
111	        );
112	      }
113	      if (status === 'done') return handleFor(spawnId, input.case.variant);
114	      if (status === 'cancelled' || status === 'reaped') {
115	        throw new Error(`runInstance: bee ${spawnId} ended '${status}' — invalid run, re-runnable`);
116	      }
117	
118	      // status === 'failed' — classify the cause from the bee's output (the canonical classifier
119	      // scans stdout on failure, incl. claude's stdout-only "· Rate limited" line).
120	      const failText = await deps.loadFailureText(spawnId).catch(() => '');
121	      const te = classifySubprocessResult({ exitCode: 1, stdout: failText });
122	      const transient = te.class === 'rate_limited' || te.class === 'overloaded';
123	
124	      if (transient && attempt < cfg.maxRateRetries) {
125	        const backoffMs = Math.max(cfg.rateBackoffMs, te.retryAfterMs ?? 0);
126	        deps.onRateLimitRetry?.({ spawnId, attempt, backoffMs, cls: te.class });
127	        await deps.sleep(backoffMs);
128	        continue; // relaunch a FRESH bee for the same case
129	      }
130	      if (transient || te.class === 'usage_limit') {
131	        // Exhausted retries (or a hard usage cap) → surface as rate-limited so the orchestrator
132	        // records `rate_limited` (NOT a scored task-failure). The 'rate-limited' in the message
133	        // triggers the orchestrator's isRateLimitError.
134	        throw new Error(
135	          `runInstance: bee ${spawnId} rate-limited (${te.class}) after ${attempt} relaunch${attempt === 1 ? '' : 'es'} — giving up`,
136	        );
137	      }
138	      // Genuine task failure (agent_crash, etc.) → a real, scoreable outcome.
139	      return handleFor(spawnId, input.case.variant);
140	    }
141	  };
142	}
