250	        extras: [`APIARY_CASE=${runInput.case.id}`, `APIARY_REPEAT=${runInput.repeat}`],
251	      });
252	      return { ok: res.ok, spawnId: res.spawnId, error: res.error };
253	    },
254	    async pollStatus(spawnId) {
255	      const rows = await args.sql<{ status: string }[]>`
256	        SELECT status FROM harness_shared.spawned_agents WHERE spawn_id = ${spawnId} LIMIT 1`;
257	      return rows[0]?.status ?? null;
