261	        SELECT output_tail, error_message FROM harness_shared.spawned_agents WHERE spawn_id = ${spawnId} LIMIT 1`;
262	      const r = rows[0];
263	      return `${r?.error_message ?? ''}\n${r?.output_tail ?? ''}`;
264	    },
265	    loadCost: (spawnId) => loadCostBySpawn(args.sql, spawnId),
