1	/**
2	 * beekeeper-gen0-runner.ts — the LIVE generation-0 IQ battery runner
3	 * (Apiary `apiary-generation-0-battery` P-004 / P-003 / P-005 / P-006).
4	 *
5	 * Replaces the PART-B stub (random scores, ephemeral getTestPg). This wires the REAL battery:
6	 *   - solver bees (opus-4-8 @ xhigh — pinned via AGENT_MODELS) administer one corpus case each (P-001);
7	 *   - their REAL transcripts + signals are distilled + collected (P-002 / D-004);
8	 *   - a REAL opus-4-8 judge scores each run (P-003);
9	 *   - everything persists to the LIVE org PG via BeekeeperStorePg + iq_battery_metrics (D-005);
10	 *   - a hard total-$spend cap + a cost-estimate preamble + a --dry-run (skip-judge) mode (P-005).
11	 *
12	 * Trigger (P-006): this is the documented CLI the Queen places onto a bee as a real mission, so the
13	 * now-working Queen loop drives the baseline end-to-end (dogfood). It also runs standalone on the host.
14	 *
15	 * Usage:
16	 *   tsx beekeeper-gen0-runner.ts --harness=<slug> [--dry-run] [--cap=50] [--cases=1] [--repeats=1] \
17	 *                                [--workspace=<id>] [--timeout-ms=600000] [--poll-ms=5000]
18	 *
19	 *   --dry-run     administer + collect + persist runs, SKIP the judge → $0 judge spend (plumbing smoke, P-008)
20	 *   --cap=<usd>   hard total-spend ceiling; the run aborts the instant a charge would exceed it (default $50)
21	 *   --cases=<n>   cases per variant (default 1 → 4 judged cases for the first baseline; P-009)
22	 *   --repeats=<n> repeats per case for noise calibration (default 1)
23	 *
24	 * The pure pieces (parseGen0Args / makeSpend) are exported + unit-tested; the battery itself is live.
25	 */
26	import { execFileSync } from 'node:child_process';
27	import type postgres from 'postgres';
28	import { getOrgPg } from '@papercusp/db-org';
29	import { activeWorkspaceId } from '../workspace-registry';
30	import { isCliEntry } from '../util/cli-entry';
31	import { runBeekeeperBattery, type BeekeeperConfig, type BeekeeperDeps } from './beekeeper-runner';
32	import { seedCorpus, type TaskVariant, type CorpusCase, type Rubric } from './corpus';
33	import { createMetricsCollector } from './collectors';
34	import { BeekeeperStorePg } from './beekeeper-store-pg';
35	import { makeBeeRunInstance, liveBeeRunDeps, makeLiveBeeTraceLoaders, type BeeRunDeps } from './bee-instance';
36	import { makeBeeCollectAndDistill } from './bee-trace';
37	import type { GymJudgeRubric } from '../gym/judge-scoring';
38	import type { JudgeLlmCall } from '../gym/judge';
39	import type { InstanceBootSpec } from './instance-manifest';
40	
41	const VARIANTS: TaskVariant[] = ['fix-injected-bug', 'build-spec', 'find-the-flaw', 'answer-from-colony-memory'];
42	
43	/** Conservative per-call estimates for the pre-flight cost preamble + the pre-emptive cap check. */
44	const JUDGE_COST_ESTIMATE_USD = 0.5; // 1 opus-4-8 judge call (~32k thinking + ~5k trace)
45	const SOLVER_COST_ESTIMATE_USD = 1.5; // 1 opus-4-8-xhigh solver bee solving one case
46	
47	// ───────────────────────────── pure, unit-tested pieces ─────────────────────────────
48	
49	export interface Gen0Args {
50	  dryRun: boolean;
51	  capUsd: number;
52	  casesPerVariant: number;
53	  repeats: number;
54	  /** Restrict to a CSV subset of variants (e.g. a 1-bee smoke); null = all four. */
55	  variants: string[] | null;
56	  workspaceId: string | null;
57	  harness: string | null;
58	  timeoutMs: number;
59	  pollMs: number;
60	  /** Max relaunches of a bee that fails on a transient rate-limit/overload. */
61	  maxRateRetries: number;
62	  /** Floor backoff before a rate-limit relaunch (ms); the server's retry-after wins when larger. */
63	  rateBackoffMs: number;
64	}
65	
66	/** Parse the CLI flags. Pure (no env/PG); `--workspace`/`--harness` default null → resolved by main. */
67	export function parseGen0Args(argv: string[]): Gen0Args {
68	  const get = (name: string): string | undefined => {
69	    const pre = `--${name}=`;
70	    const hit = argv.find((a) => a.startsWith(pre));
71	    return hit ? hit.slice(pre.length) : undefined;
72	  };
73	  const has = (name: string): boolean => argv.includes(`--${name}`);
74	  const num = (v: string | undefined, dflt: number): number => {
75	    if (v === undefined) return dflt;
76	    const x = Number(v);
77	    return Number.isFinite(x) ? x : dflt;
78	  };
79	  return {
80	    dryRun: has('dry-run'),
81	    capUsd: num(get('cap'), 50),
82	    casesPerVariant: Math.max(1, Math.floor(num(get('cases'), 1))),
83	    repeats: Math.max(1, Math.floor(num(get('repeats'), 1))),
84	    variants: (() => {
85	      const raw = get('variants');
86	      if (!raw) return null;
87	      const list = raw.split(',').map((s) => s.trim()).filter(Boolean);
88	      return list.length ? list : null;
89	    })(),
90	    workspaceId: get('workspace') ?? null,
91	    harness: get('harness') ?? null,
92	    timeoutMs: num(get('timeout-ms'), 600_000),
93	    pollMs: num(get('poll-ms'), 5_000),
94	    maxRateRetries: Math.max(0, Math.floor(num(get('rate-retries'), 3))),
95	    rateBackoffMs: num(get('rate-backoff-ms'), 30_000),
96	  };
97	}
98	
99	export class SpendCapError extends Error {
100	  constructor(public readonly capUsd: number, public readonly attemptedUsd: number) {
101	    super(`spend cap $${capUsd} would be exceeded (attempted total $${attemptedUsd.toFixed(4)}) — battery aborted`);
102	    this.name = 'SpendCapError';
103	  }
104	}
105	
106	export interface Spend {
107	  readonly usd: number;
108	  /** Add `amount` (negatives ignored); throw SpendCapError BEFORE recording if it would exceed the cap. */
109	  charge(amount: number, label: string): void;
110	}
111	
112	/** A hard total-spend ceiling. `charge` throws the instant a charge would cross `capUsd`. */
113	export function makeSpend(capUsd: number): Spend {
114	  let usd = 0;
115	  return {
116	    get usd() {
117	      return usd;
118	    },
119	    charge(amount: number) {
120	      const next = usd + Math.max(0, amount);
121	      if (next > capUsd) throw new SpendCapError(capUsd, next);
122	      usd = next;
123	    },
124	  };
125	}
126	
127	/** The committed gen-0 GYM judge rubric (opus-4-8, deterministic). */
128	export function buildRubric(): GymJudgeRubric {
129	  return {
130	    version: 'gen0-v1',
131	    model: 'claude-opus-4-8',
132	    temperature: 0,
133	    thinkingBudgetTokens: 32_000,
134	    weights: { d1: 0.5, d2: 0.25, d3: 0.25 },
135	    dimensions: {
136	      d1: 'Intent & spec fidelity: did the work achieve the high-level INTENT',
137	      d2: 'Code quality: clarity, minimality, and absence of needless complexity',
138	      d3: 'Process correctness: did the bee behave well (sound steps, no flailing)',
139	    },
140	  } as unknown as GymJudgeRubric;
141	}
142	
143	/** The instance manifest = a fingerprint of the SOLVER under test (commit + model) for re-runnability. */
144	export function buildManifest(workspaceId: string): InstanceBootSpec {
145	  let codeSha = 'unknown';
146	  try {
147	    codeSha = execFileSync('git', ['rev-parse', '--short', 'HEAD'], { encoding: 'utf8' }).trim() || 'unknown';
148	  } catch {
149	    /* not a git checkout / git absent — manifest still records model + ts */
150	  }
151	  return {
152	    manifest: {
153	      instanceId: `gen0-${codeSha}-${workspaceId}`,
154	      workspaceId,
155	      codeSha,
156	      createdAt: new Date(),
157	    },
158	    instanceUrl: `solver://bee/opus-4-8-xhigh@${codeSha}`,
159	  };
160	}
161	
162	// ───────────────────────────── the live orchestration ─────────────────────────────
163	
164	/** A judge that skips the real LLM call (dry-run): zero score, zero spend — validates plumbing. */
165	const dryRunJudge: JudgeLlmCall = async () => ({
166	  text: JSON.stringify({ d1: 0, d2: 0, d3: 0, rationale: 'dry-run (judge skipped)' }),
167	  json: { d1: 0, d2: 0, d3: 0, rationale: 'dry-run (judge skipped)' },
168	  costUsd: 0,
169	  inputTokens: 0,
170	  outputTokens: 0,
171	});
172	
173	/** Pre-flight: fail loud with a clear message if the beekeeper schema isn't applied on the live PG. */
174	async function assertSchema(sql: postgres.Sql): Promise<void> {
175	  const rows = await sql<{ ok: boolean }[]>`
176	    SELECT to_regclass('harness_shared.beekeeper_runs') IS NOT NULL
177	       AND to_regclass('iq_battery_cases') IS NOT NULL AS ok`;
178	  if (!rows[0]?.ok) {
179	    throw new Error(
180	      'beekeeper/iq-battery schema missing on the live org PG — apply migrations 179 + 180 (db:migrate) before running the baseline.',
181	    );
182	  }
183	}
184	
185	/**
186	 * Load the seeded corpus back from iq_battery_cases — the in-memory corpus data carries NO `id`
187	 * (it's assigned at seed time via generateStableCaseId), and the battery keys runs by case id. One
188	 * single-value-bound query per variant (bulletproof binds), capped at `casesPerVariant`.
189	 */
190	async function loadSeededCorpus(
191	  sql: postgres.Sql,
192	  variants: TaskVariant[],
193	  casesPerVariant: number,
194	): Promise<CorpusCase[]> {
195	  const corpus: CorpusCase[] = [];
196	  for (const variant of variants) {
197	    const rows = await sql<
198	      {
199	        id: string;
200	        variant: string;
201	        title: string;
202	        prompt: string;
203	        ground_truth: Record<string, unknown>;
204	        rubric: unknown;
205	        rotation_index: number;
206	      }[]
207	    >`
208	      SELECT id, variant, title, prompt, ground_truth, rubric, rotation_index
209	        FROM iq_battery_cases
210	       WHERE variant = ${variant}
211	       ORDER BY rotation_index
212	       LIMIT ${casesPerVariant}`;
213	    for (const r of rows) {
214	      // jsonb may arrive parsed (object) or raw (string) depending on the pool's parse config —
215	      // normalize so groundTruth/rubric are always objects.
216	      const asObj = (v: unknown, dflt: unknown): unknown => {
217	        if (v == null) return dflt;
218	        if (typeof v === 'string') {
219	          try {
220	            return JSON.parse(v);
221	          } catch {
222	            return dflt;
223	          }
224	        }
225	        return v;
226	      };
227	      corpus.push({
228	        id: r.id,
229	        variant: r.variant as TaskVariant,
230	        title: r.title,
231	        prompt: r.prompt,
232	        groundTruth: asObj(r.ground_truth, {}) as Record<string, unknown>,
233	        rubric: asObj(r.rubric, { dimensions: [] }) as Rubric,
234	        rotationIndex: r.rotation_index,
235	        createdAt: new Date(),
236	      });
237	    }
238	  }
239	  return corpus;
240	}
241	
242	/** Transfer the freshly-recorded beekeeper_scores → iq_battery_metrics (the recurrence + Tests-tab source). */
243	async function transferMetrics(sql: postgres.Sql, instanceId: string): Promise<number> {
244	  const runs = await sql<{ run_id: string; case_id: string; case_variant: string }[]>`
245	    SELECT run_id, case_id, case_variant FROM harness_shared.beekeeper_runs WHERE instance_id = ${instanceId}`;
246	  let transferred = 0;
247	  for (const run of runs) {
248	    const scores = await sql<
249	      {
250	        success: boolean;
251	        tokens_per_task: number | null;
252	        time_to_green_secs: number | null;
253	        first_attempt_pass: boolean;
254	        recurrence: number;
255	        escalation: boolean;
256	        recall_hit: number;
257	      }[]
258	    >`
259	      SELECT success, tokens_per_task, time_to_green_secs, first_attempt_pass, recurrence, escalation, recall_hit
260	        FROM harness_shared.beekeeper_scores WHERE run_id = ${run.run_id} LIMIT 1`;
261	    const s = scores[0];
262	    if (!s) continue;
263	    // Idempotent transfer (D-005): iq_battery_metrics.run_id is a UUID column but the beekeeper
264	    // run_id is TEXT, so we can't store the run_id directly. Derive a DETERMINISTIC uuid from it
265	    // (md5(text)::uuid) so a re-run of the same beekeeper run maps to the SAME metric row and
266	    // ON CONFLICT (run_id, case_id) overwrites it — instead of gen_random_uuid() appending a fresh
267	    // duplicate every transfer (the bug that accreted 19 dup rows over the dev runs).
268	    await sql`
269	      INSERT INTO iq_battery_metrics (
270	        run_id, case_id, variant, success, tokens_per_solved_task, time_to_green_secs,
271	        first_attempt_pass, recurrence, escalation, recall_hit
272	      ) VALUES (
273	        md5(${run.run_id})::uuid, ${run.case_id}, ${run.case_variant}, ${s.success}, ${s.tokens_per_task},
274	        ${s.time_to_green_secs}, ${s.first_attempt_pass}, ${s.recurrence}, ${s.escalation}, ${s.recall_hit}
275	      )
276	      ON CONFLICT (run_id, case_id) DO UPDATE SET
277	        variant = EXCLUDED.variant,
278	        success = EXCLUDED.success,
279	        tokens_per_solved_task = EXCLUDED.tokens_per_solved_task,
280	        time_to_green_secs = EXCLUDED.time_to_green_secs,
281	        first_attempt_pass = EXCLUDED.first_attempt_pass,
282	        recurrence = EXCLUDED.recurrence,
283	        escalation = EXCLUDED.escalation,
284	        recall_hit = EXCLUDED.recall_hit,
285	        collected_at = now()`;
286	    transferred += 1;
287	  }
288	  return transferred;
289	}
290	
291	/** Build the live deps (cap-wrapped solver + judge) + config, run the battery, transfer + report. */
292	export async function runGen0Battery(args: Gen0Args): Promise<void> {
293	  const workspaceId = args.workspaceId ?? activeWorkspaceId();
294	  if (!args.harness) throw new Error('--harness=<slug> is required (the harness the solver bees spawn into)');
295	
296	  // Pin solver bees to opus-4-8 @ xhigh deterministically (bees have no committed ROLE_MODEL_DEFAULTS
297	  // floor), and ENABLE the shared AIMD governor so a bee 429 halves the effective concurrency cap
298	  // (the "lower cap" half of the hit-limit → lower-cap → relaunch loop).
299	  const priorEnv = {
300	    AGENT_MODELS: process.env.AGENT_MODELS,
301	    PAPERCUSP_AGENT_GOVERNOR: process.env.PAPERCUSP_AGENT_GOVERNOR,
302	    PAPERCUSP_AGENT_GOVERNOR_PG: process.env.PAPERCUSP_AGENT_GOVERNOR_PG,
303	    LLM_TEST_BACKEND: process.env.LLM_TEST_BACKEND,
304	  };
305	  try {
306	    const merged = { ...(priorEnv.AGENT_MODELS ? safeJson(priorEnv.AGENT_MODELS) : {}), bee: 'opus:xhigh' };
307	    process.env.AGENT_MODELS = JSON.stringify(merged);
308	    process.env.PAPERCUSP_AGENT_GOVERNOR = '1';
309	    process.env.PAPERCUSP_AGENT_GOVERNOR_PG = '1';
310	    // The judge is an IN-PROCESS llmCall on THIS box; llm-client's default anthropic-direct
311	    // backend rides the owner's volatile ~/.claude session and shares its rate bucket. Route the
312	    // judge through the claude CLI on the same clean OAuth token the bees already use
313	    // (CLAUDE_CODE_OAUTH_TOKEN), unless the caller explicitly set a backend. (Originally also
314	    // dodged the pre-EI-399 default that pointed at the dead :3456 router and wedged the
315	    // sequential battery in an endless retry loop.)
316	    process.env.LLM_TEST_BACKEND = process.env.LLM_TEST_BACKEND ?? 'claude-code';
317	
318	    const { sql } = getOrgPg();
319	    await assertSchema(sql);
320	    await seedCorpus(sql);
321	
322	    const variants = args.variants ? VARIANTS.filter((v) => args.variants!.includes(v)) : VARIANTS;
323	    if (variants.length === 0) {
324	      throw new Error(`--variants matched none of the corpus variants; valid: ${VARIANTS.join(', ')}`);
325	    }
326	    const corpus: CorpusCase[] = await loadSeededCorpus(sql, variants, args.casesPerVariant);
327	    if (corpus.length === 0) {
328	      throw new Error(`no seeded cases for variants [${variants.join(', ')}] — seedCorpus may have failed`);
329	    }
330	    const spec = buildManifest(workspaceId);
331	    const config: BeekeeperConfig = {
332	      instanceSpec: spec,
333	      corpus,
334	      repeats: args.repeats,
335	      rubric: buildRubric(),
336	      maxDistillChars: 5_000,
337	    };
338	
339	    const totalRuns = corpus.length * args.repeats;
340	    const estMax = totalRuns * (SOLVER_COST_ESTIMATE_USD + (args.dryRun ? 0 : JUDGE_COST_ESTIMATE_USD));
341	    console.log('=== Apiary generation-0 IQ battery ===');
342	    console.log(`workspace=${workspaceId} harness=${args.harness} solver=opus-4-8@xhigh`);
343	    console.log(`corpus=${corpus.length} cases × ${args.repeats} repeat(s) = ${totalRuns} runs`);
344	    console.log(`mode=${args.dryRun ? 'DRY-RUN (judge skipped)' : 'LIVE'}  cap=$${args.capUsd}  est-max≈$${estMax.toFixed(2)}`);
345	    if (estMax > args.capUsd) {
346	      console.warn(`⚠ estimated max ($${estMax.toFixed(2)}) exceeds cap ($${args.capUsd}) — the cap will abort the run partway. Raise --cap or lower --cases/--repeats.`);
347	    }
348	
349	    const spend = makeSpend(args.capUsd);
350	
351	    // Real runInstance, wrapped to charge solver cost against the cap. A bee that fails on a
352	    // transient rate-limit / overload is RELAUNCHED (maxRateRetries) — the fleet AIMD governor
353	    // lowers concurrency in parallel (enabled via PAPERCUSP_AGENT_GOVERNOR below).
354	    const beeDeps: BeeRunDeps = {
355	      ...liveBeeRunDeps({ sql, workspaceId, harness: args.harness, planSlug: 'apiary-generation-0-battery-2026-06-08' }),
356	      onRateLimitRetry: ({ spawnId, attempt, backoffMs, cls }) =>
357	        console.log(
358	          `  ↻ rate-limit relaunch: bee=${spawnId} cls=${cls} attempt=${attempt + 1}/${args.maxRateRetries} backoff=${Math.round(backoffMs / 1000)}s`,
359	        ),
360	    };
361	    const baseRunInstance = makeBeeRunInstance(
362	      { timeoutMs: args.timeoutMs, pollMs: args.pollMs, maxRateRetries: args.maxRateRetries, rateBackoffMs: args.rateBackoffMs },
363	      beeDeps,
364	    );
365	
366	    // Real judge (opus-4-8) unless dry-run; wrapped to pre-check + charge judge cost.
367	    const realJudge: JudgeLlmCall = (await import('../llm-testing/llm-client')).llmCall;
368	    // Bound each judge llmCall so a stuck/slow judge (e.g. an unreachable backend's internal retry
369	    // loop) errors only THIS case (battery → status 'errored', continues) instead of wedging the
370	    // whole sequential run. A real opus-4-8 judge returns in <2min; 4min is a generous ceiling.
371	    const JUDGE_TIMEOUT_MS = 240_000;
372	    const judge: JudgeLlmCall = args.dryRun
373	      ? dryRunJudge
374	      : async (opts) => {
375	          if (spend.usd + JUDGE_COST_ESTIMATE_USD > args.capUsd) {
376	            throw new SpendCapError(args.capUsd, spend.usd + JUDGE_COST_ESTIMATE_USD);
377	          }
378	          let timer: ReturnType<typeof setTimeout> | undefined;
379	          const r = await Promise.race([
380	            realJudge(opts),
381	            new Promise<never>((_, reject) => {
382	              timer = setTimeout(
383	                () => reject(new Error(`judge llmCall timed out after ${JUDGE_TIMEOUT_MS / 1000}s`)),
384	                JUDGE_TIMEOUT_MS,
385	              );
386	            }),
387	          ]).finally(() => {
388	            if (timer) clearTimeout(timer);
389	          });
390	          spend.charge(r.costUsd, 'judge');
391	          return r;
392	        };
393	
394	    const metricsCollector = await createMetricsCollector(sql);
395	    const deps: BeekeeperDeps = {
396	      store: new BeekeeperStorePg(sql),
397	      runInstance: async (input) => {
398	        if (spend.usd + SOLVER_COST_ESTIMATE_USD > args.capUsd) {
399	          throw new SpendCapError(args.capUsd, spend.usd + SOLVER_COST_ESTIMATE_USD);
400	        }
401	        const handle = await baseRunInstance(input);
402	        spend.charge(handle.costUsd, 'solver');
403	        return handle;
404	      },
405	      collectAndDistill: makeBeeCollectAndDistill(makeLiveBeeTraceLoaders(sql)),
406	      collectMetrics: (input) => metricsCollector.collectMetrics(input),
407	      llmCall: judge,
408	      newRunId: (caseId, repeat) => `gen0-${spec.manifest.codeSha}-${(caseId ?? 'nocase').slice(0, 12)}-r${repeat}`,
409	      now: () => Date.now(),
410	    };
411	
412	    console.log('\nrunning battery…');
413	    const result = await runBeekeeperBattery(config, deps);
414	
415	    const scored = result.outcomes.filter((o) => o.status === 'scored').length;
416	    const errored = result.outcomes.filter((o) => o.status === 'errored').length;
417	    const rateLimited = result.outcomes.filter((o) => o.status === 'rate_limited').length;
418	    console.log('\n=== results ===');
419	    console.log(`scored=${scored} errored=${errored} rate_limited=${rateLimited} of ${result.totalCases}`);
420	    console.log(`meanComposite=${result.meanComposite.toFixed(3)} rubricHash=${result.rubricHash} spend≈$${spend.usd.toFixed(4)}`);
421	    for (const o of result.outcomes) {
422	      console.log(`  ${o.caseVariant} ${o.runId}: ${o.status}${o.error ? ` — ${o.error}` : ` composite=${o.composite.toFixed(2)}`}`);
423	    }
424	
425	    const transferred = await transferMetrics(sql, spec.manifest.instanceId);
426	    console.log(`\ntransferred ${transferred} score(s) → iq_battery_metrics`);
427	    console.log(`\n✓ gen-0 ${args.dryRun ? 'dry-run' : 'baseline'} complete (spend $${spend.usd.toFixed(4)} / cap $${args.capUsd})`);
428	  } finally {
429	    for (const [k, v] of Object.entries(priorEnv)) {
430	      if (v === undefined) delete process.env[k];
431	      else process.env[k] = v;
432	    }
433	  }
434	}
435	
436	function safeJson(s: string): Record<string, unknown> {
437	  try {
438	    const v = JSON.parse(s);
439	    return v && typeof v === 'object' ? (v as Record<string, unknown>) : {};
440	  } catch {
441	    return {};
442	  }
443	}
444	
445	async function main(): Promise<void> {
446	  await runGen0Battery(parseGen0Args(process.argv.slice(2)));
447	}
448	
449	// ESM main-module guard: run only when invoked directly, NEVER on import (so tests
450	// don't spend) and NEVER when bundled into the desktop sidecar (see isCliEntry / EI-650).
451	if (isCliEntry(import.meta.url)) {
452	  main()
453	    .then(() => process.exit(0))
454	    .catch((err) => {
455	      console.error(err instanceof Error ? err.stack ?? err.message : String(err));
456	      process.exit(1);
457	    });
458	}
